create extension if not exists pgcrypto;
create table if not exists public.departments(id uuid primary key default gen_random_uuid(),name text not null unique,sort_order int not null default 0);
create table if not exists public.agents(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,slug text not null,name text not null,department_id uuid references public.departments(id),role text not null,description text not null default '',capabilities text[] not null default '{}',commands text[] not null default '{}',is_custom boolean not null default false,is_archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,slug));
create table if not exists public.agent_versions(id uuid primary key default gen_random_uuid(),agent_id uuid not null references public.agents(id) on delete cascade,version int not null,instructions text not null,change_note text not null default '',created_at timestamptz not null default now(),unique(agent_id,version));
create table if not exists public.agent_favourites(owner_id uuid not null references auth.users(id) on delete cascade,agent_id uuid not null references public.agents(id) on delete cascade,created_at timestamptz not null default now(),primary key(owner_id,agent_id));
create table if not exists public.agent_recent(owner_id uuid not null references auth.users(id) on delete cascade,agent_id uuid not null references public.agents(id) on delete cascade,last_opened_at timestamptz not null default now(),primary key(owner_id,agent_id));
create table if not exists public.prompt_templates(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null default '',category text not null default 'General',tags text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.departments enable row level security; alter table public.agents enable row level security; alter table public.agent_versions enable row level security; alter table public.agent_favourites enable row level security; alter table public.agent_recent enable row level security; alter table public.prompt_templates enable row level security;
create policy "read departments" on public.departments for select to authenticated using(true);
create policy "own agents" on public.agents for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "own versions" on public.agent_versions for all to authenticated using(exists(select 1 from public.agents a where a.id=agent_id and a.owner_id=auth.uid())) with check(exists(select 1 from public.agents a where a.id=agent_id and a.owner_id=auth.uid()));
create policy "own favourites" on public.agent_favourites for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "own recent" on public.agent_recent for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "own prompts" on public.prompt_templates for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
insert into public.departments(name,sort_order) values('Creative & Art',1),('Web & Digital',2),('Brands & Marketing',3),('Industrial & Operations',4),('Business & Commerce',5),('Technology & AI',6) on conflict(name) do nothing;